mapper.sql:
WITH match_raw AS ( SELECT m.match_id,m.season_id,m.round_id,m.home_club_id,hc.club_name home_club_name, ac.club_name away_club_name,m.match_time,m.match_status, (SELECT COUNT(*) FROM match_seat_inventory i WHERE i.match_id=m.match_id AND i.inventory_status!='DISABLED') total_seat_count, (SELECT COUNT(*) FROM order_item oi JOIN ticket_order o ON o.order_id=oi.order_id WHERE o.match_id=m.match_id AND oi.item_status='PAID') valid_sold_count, (SELECT COUNT(*) FROM order_item oi JOIN ticket_order o ON o.order_id=oi.order_id WHERE o.match_id=m.match_id AND oi.item_status='REFUNDED') refunded_count, (SELECT COUNT(*) FROM e_ticket t JOIN ticket_order o ON o.order_id=t.order_id WHERE o.match_id=m.match_id AND t.ticket_status='USED') checked_in_count, COALESCE((SELECT SUM(p.pay_amount) FROM payment_record p JOIN ticket_order o ON o.order_id=p.order_id WHERE o.match_id=m.match_id AND p.pay_status='SUCCESS'),0.00) gross_sales_amount, COALESCE((SELECT SUM(r.refund_amount) FROM refund_apply r JOIN ticket_order o ON o.order_id=r.order_id WHERE o.match_id=m.match_id AND r.refund_status='APPROVED'),0.00) refund_amount, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='SUCCESS') success_count, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='CODE_NOT_FOUND') code_not_found_count, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='WRONG_MATCH') wrong_match_count, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='ORDER_INVALID') order_invalid_count, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='TICKET_USED') ticket_used_count, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='TICKET_REFUNDED') ticket_refunded_count, (SELECT COUNT(*) FROM checkin_record c WHERE c.match_id=m.match_id AND c.check_result='TICKET_VOID') ticket_void_count FROM match_info m JOIN club_info hc ON hc.club_id=m.home_club_id JOIN club_info ac ON ac.club_id=m.away_club_id WHERE 1=1 AND m.season_id=#{q.seasonId} AND m.round_id=#{q.roundId}
AND m.home_club_id=#{clubScope} AND (m.home_club_id=#{q.clubId} OR m.away_club_id=#{q.clubId})
AND m.match_status=#{q.matchStatus} AND m.match_time>=#{q.startTime} AND m.match_time<=#{q.endTime} ), match_stats AS ( SELECT r.*, CAST(r.gross_sales_amount-r.refund_amount AS DECIMAL(14,2)) net_sales_amount, CAST(CASE WHEN r.total_seat_count=0 THEN 0 ELSE ROUND(r.valid_sold_count*100.0/r.total_seat_count,2) END AS DECIMAL(7,2)) ticket_sale_rate, CAST(CASE WHEN r.total_seat_count=0 THEN 0 ELSE ROUND(r.checked_in_count*100.0/r.total_seat_count,2) END AS DECIMAL(7,2)) attendance_rate FROM match_raw r )

mapper.select:
SELECT stat_date,CAST(SUM(gross_amount) AS DECIMAL(14,2)) gross_sales_amount,
       CAST(SUM(refund_amount) AS DECIMAL(14,2)) refund_amount,
       CAST(SUM(gross_amount)-SUM(refund_amount) AS DECIMAL(14,2)) net_sales_amount,
       SUM(tickets_sold) tickets_sold
FROM (
    SELECT DATE(p.pay_time) stat_date,SUM(p.pay_amount) gross_amount,0.00 refund_amount,SUM(o.ticket_count) tickets_sold
    FROM payment_record p JOIN ticket_order o ON o.order_id=p.order_id JOIN match_info m ON m.match_id=o.match_id
    WHERE p.pay_status='SUCCESS'
    AND m.season_id=#{q.seasonId}
    AND p.pay_time>=#{q.startTime}
    AND p.pay_time<=#{q.endTime}
    GROUP BY DATE(p.pay_time)
    UNION ALL
    SELECT DATE(r.audit_time),0.00,SUM(r.refund_amount),0
    FROM refund_apply r JOIN ticket_order o ON o.order_id=r.order_id JOIN match_info m ON m.match_id=o.match_id
    WHERE r.refund_status='APPROVED'
    AND m.season_id=#{q.seasonId}
    AND r.audit_time>=#{q.startTime}
    AND r.audit_time<=#{q.endTime}
    GROUP BY DATE(r.audit_time)
) daily GROUP BY stat_date ORDER BY stat_date
